import React, { useState, useEffect } from 'react';

interface Branch {
  id: number;
  branchName: string;
}

interface UnitItem {
  id: string | number;
  name: string;
}

function UnitListPanel() {
  const [units, setUnits] = useState<UnitItem[]>([
    { id: 'all', name: 'Tất cả' }
  ]);
  const [activeUnit, setActiveUnit] = useState<string | number>('all');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchBranches = async () => {
      try {
        setLoading(true);
        const response = await fetch('http://localhost:8080/api/branches/getAllBranches');
        if (!response.ok) {
          throw new Error('Failed to fetch branches');
        }
        const branches: Branch[] = await response.json();

        // Create units array with "Tất cả" as first item
        const unitItems: UnitItem[] = [
          { id: 'all', name: 'Tất cả' },
          ...branches.map(branch => ({
            id: branch.id,
            name: branch.branchName
          }))
        ];

        setUnits(unitItems);
        setError('');
      } catch (err) {
        console.error('Error fetching branches:', err);
        setError('Không thể tải danh sách đơn vị');
        // Keep the default "Tất cả" item if API fails
        setUnits([{ id: 'all', name: 'Tất cả' }]);
      } finally {
        setLoading(false);
      }
    };

    fetchBranches();
  }, []);

  return (
    <section className="panel unit-panel" aria-label="Danh sách đơn vị">
      <header className="panel-header">
        <h2>Danh sách đơn vị</h2>
      </header>
      <div className="panel-search">
        <input type="text" placeholder="Tìm kiếm" aria-label="Tìm kiếm đơn vị" />
      </div>
      <div className="unit-list" role="listbox" aria-label="Danh sách chi nhánh">
        {loading ? (
          <div style={{ padding: '16px', textAlign: 'center', color: '#999' }}>
            Đang tải...
          </div>
        ) : error ? (
          <div style={{ padding: '16px', textAlign: 'center', color: '#d32f2f' }}>
            {error}
          </div>
        ) : (
          units.map((unit) => (
            <button
              key={unit.id}
              type="button"
              className={`unit-item ${activeUnit === unit.id ? 'unit-item-active' : ''}`}
              aria-selected={activeUnit === unit.id}
              onClick={() => setActiveUnit(unit.id)}
            >
              {unit.name}
            </button>
          ))
        )}
      </div>
    </section>
  );
}

export default UnitListPanel;

import React, { useState, useEffect } from 'react';

interface Branch {
  id: number;
  branchName: string;
}

interface UnitItem {
  id: string | number;
  name: string;
}

interface UnitListPanelProps {
  onBranchSelect?: (branchId: string | number) => void;
}

function UnitListPanel({ onBranchSelect }: UnitListPanelProps) {
  const [units, setUnits] = useState<UnitItem[]>([
    { id: 'all', name: 'Tất cả' }
  ]);
  const [activeUnit, setActiveUnit] = useState<string | number>('all');
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState('');

  useEffect(() => {
    const fetchBranches = async () => {
      try {
        setLoading(true);
        const response = await fetch('http://localhost:8080/api/branches/getAllBranches');
        if (!response.ok) {
          throw new Error('Failed to fetch branches');
        }
        const branches: Branch[] = await response.json();

        // Create units array with "Tất cả" as first item
        const unitItems: UnitItem[] = [
          { id: 'all', name: 'Tất cả' },
          ...branches.map(branch => ({
            id: branch.id,
            name: branch.branchName
          }))
        ];

        setUnits(unitItems);
        setError('');
      } catch (err) {
        console.error('Error fetching branches:', err);
        setError('Không thể tải danh sách đơn vị');
        // Keep the default "Tất cả" item if API fails
        setUnits([{ id: 'all', name: 'Tất cả' }]);
      } finally {
        setLoading(false);
      }
    };

    fetchBranches();
  }, []);

  const handleUnitClick = (unitId: string | number) => {
    setActiveUnit(unitId);
    onBranchSelect?.(unitId);
  };

  return (
    <section className="panel unit-panel" aria-label="Danh sách đơn vị">
      <header className="panel-header">
        <h2>Danh sách đơn vị</h2>
      </header>
      <div className="panel-search">
        <input type="text" placeholder="Tìm kiếm" aria-label="Tìm kiếm đơn vị" />
      </div>
      <div className="unit-list" role="listbox" aria-label="Danh sách chi nhánh">
        {loading ? (
          <div style={{ padding: '16px', textAlign: 'center', color: '#999' }}>
            Đang tải...
          </div>
        ) : error ? (
          <div style={{ padding: '16px', textAlign: 'center', color: '#d32f2f' }}>
            {error}
          </div>
        ) : (
          units.map((unit) => (
            <button
              key={unit.id}
              type="button"
              className={`unit-item ${activeUnit === unit.id ? 'unit-item-active' : ''}`}
              aria-selected={activeUnit === unit.id}
              onClick={() => handleUnitClick(unit.id)}
            >
              {unit.name}
            </button>
          ))
        )}
      </div>
    </section>
  );
}

export default UnitListPanel;

import { CreateContractRequestDTO, ApiResponse, ContractDTO } from '../types/contract';

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || 'http://localhost:8080/api';

// Helper functions
async function sendJson(request: CreateContractRequestDTO): Promise<ContractDTO> {
  const response = await fetch(`${API_BASE_URL}/contracts/init`, {
    method: 'POST',
    headers: {
      'Content-Type': 'application/json',
      'Authorization': `Bearer ${localStorage.getItem('accessToken') || ''}`,
    },
    body: JSON.stringify(request),
  });

  return handleResponse(response);
}

async function sendFormData(formData: FormData): Promise<ContractDTO> {
  const response = await fetch(`${API_BASE_URL}/contracts/init`, {
    method: 'POST',
    headers: {
      'Authorization': `Bearer ${localStorage.getItem('accessToken') || ''}`,
      // Không set Content-Type, browser sẽ tự động set multipart/form-data
    },
    body: formData,
  });

  return handleResponse(response);
}

async function handleResponse(response: Response): Promise<ContractDTO> {
  if (!response.ok) {
    const errorData = await response.json().catch(() => ({}));
    throw new Error(errorData.message || `HTTP error! status: ${response.status}`);
  }

  const data: ApiResponse<ContractDTO> = await response.json();

  if (data.code !== 'SUCCESS') {
    throw new Error(data.message || 'Lỗi tạo hợp đồng');
  }

  return data.data;
}

export const contractService = {
  /**
   * Khởi tạo hợp đồng thử việc
   * @param request Dữ liệu hợp đồng
   * @param files Danh sách files tải lên (tùy chọn)
   * @returns Promise<ContractDTO>
   */
  async initContract(request: CreateContractRequestDTO, files?: File[]): Promise<ContractDTO> {
    try {
      // Convert display dates (dd/MM/yyyy) to ISO format (yyyy-MM-dd) for API
      const apiRequest = {
        ...request,
        decisionDate: convertToIsoDate(request.decisionDate),
        dateOfBirth: convertToIsoDate(request.dateOfBirth),
        dateIssued: convertToIsoDate(request.dateIssued),
        startDate: convertToIsoDate(request.startDate),
        endDate: convertToIsoDate(request.endDate),
      };

      // Nếu có files, sử dụng FormData (multipart/form-data endpoint)
      if (files && files.length > 0) {
        const formData = new FormData();

        // Thêm request object dưới dạng Blob JSON trong field "contract"
        // Điều quan trọng: Blob sẽ có Content-Type: application/json
        // String JSON sẽ có Content-Type: text/plain (Spring không deserialize được)
        const contractBlob = new Blob([JSON.stringify(apiRequest)], { type: 'application/json' });
        formData.append('contract', contractBlob, 'contract.json');

        // Thêm files vào field "attachments"
        files.forEach((file) => {
          formData.append('attachments', file);
        });

        return sendFormData(formData);
      } else {
        // Không có files, sử dụng JSON endpoint
        return sendJson(apiRequest);
      }
    } catch (error) {
      console.error('Error calling initContract API:', error);
      throw error;
    }
  },
};

// Helper function to convert display date format (dd/MM/yyyy) to ISO format (yyyy-MM-dd)
function convertToIsoDate(displayDate: string): string {
  if (!displayDate) {
    return '';
  }

  // If already in ISO format, return as is
  if (/^\d{4}-\d{2}-\d{2}$/.test(displayDate)) {
    return displayDate;
  }

  // Convert from dd/MM/yyyy to yyyy-MM-dd
  const parts = displayDate.match(/^(\d{2})\/(\d{2})\/(\d{4})$/);
  if (!parts) {
    return displayDate;
  }

  const [, day, month, year] = parts;
  return `${year}-${month}-${day}`;
}

};

import { CreateContractRequestDTO, ApiResponse, ContractDTO } from '../types/contract';

const API_BASE_URL = process.env.REACT_APP_API_BASE_URL || 'http://localhost:8080/api';

// Helper functions
async function sendJson(request: CreateContractRequestDTO): Promise<ContractDTO> {
